import json
import os
import urllib.parse
import urllib.request

BASE = os.environ.get(
    "PRICING_BASE_URL", "http://pricing-v2.internal:8081/api/v2/price"
).rstrip("/")


def get_price(sku: str) -> float:
    """Fetch a live price using a service-specific key, when configured."""
    headers = {}
    key = os.environ.get("PRICING_API_KEY")
    if key:
        headers["X-Pricing-Key"] = key
    request = urllib.request.Request(
        f"{BASE}/{urllib.parse.quote(sku, safe='')}", headers=headers
    )
    with urllib.request.urlopen(request, timeout=5) as response:
        return float(json.load(response)["price"])


def get_total(skus: list) -> float:
    return sum((get_price(sku) for sku in skus), 0.0)
